with open(\"input.json\") as f:
    x = json.load(f)
def covered(start, end, intervals):
    cursor = start
    for left, right in sorted(intervals):
        if right <= cursor:
            continue
        if left > cursor:
            return False
        cursor = max(cursor, right)
        if cursor >= end:
            return True
    return False
starts = []
for start in range(x[\"window_start\"], x[\"window_end\"] - x[\"duration\"] + 1):
    end = start + x[\"duration\"]
    if end > x[\"deadline\"]:
        continue
    if not all(covered(start, end, intervals) for intervals in x[\"teams\"].values()):
        continue
    if any(start < right and left < end for left, right in x[\"blackouts\"]):
        continue
    starts.append(start)
print(json.dumps({\"feasible_starts\": starts, \"earliest\": starts[0] if starts else None, \"latest\": starts[-1] if starts else None}, separators=(\",\", \":\")))'"

